changeSet.sql:
 -- enable the trigram extension
 CREATE EXTENSION IF NOT EXISTS "pg_trgm";

-- add trigram index to kind in the hope to speed up like performance for paginationsearch
 CREATE INDEX IF NOT EXISTS ix_kind_name_gin ON kind USING gin(lower(name) gin_trgm_ops);
 CREATE INDEX IF NOT EXISTS ix_kind_vorname_gin ON kind USING gin(lower(vorname) gin_trgm_ops);

 CREATE INDEX IF NOT EXISTS ix_kind_esadid_gin ON kind USING gin(lower(esadid) gin_trgm_ops);

 CREATE INDEX IF NOT EXISTS ix_schule_bezeichnung_gin ON schule USING gin(lower(schulhaus) gin_trgm_ops);
 CREATE INDEX IF NOT EXISTS ix_klasse_bezeichnung_gin ON klasse USING gin(lower(bezeichnung) gin_trgm_ops);
